876	/// Resolve the top trigger from the stack.
877	/// Returns true if a trigger was resolved, false if the top of stack is not a trigger.
878	pub fn resolve_next_trigger(state: &mut GameState, registry: &CardRegistry) -> bool {
879	    // Check if the top of stack is a trigger.
880	    let is_trigger = state.stack.last()
881	        .map(|e| matches!(e, crate::state::StackEntry::Trigger(_)))
882	        .unwrap_or(false);
883	    if !is_trigger {
884	        return false;
885	    }
886	    let entry = state.stack.pop().expect("stack must have trigger entry");
887	    let trigger = match entry {
888	        crate::state::StackEntry::Trigger(t) => t,
889	        _ => unreachable!(),
890	    };
891	
892	    match trigger {
893	        PendingTrigger::EnteredBattlefield { object_id, card_id, .. } => {
894	            // Verify the object is still on the battlefield.
895	            if state.get_object(object_id).map(|o| o.zone == Zone::Battlefield).unwrap_or(false) {
896	                if let Some(behavior) = registry.get(card_id) {
897	                    behavior.on_enter_battlefield(state, object_id, registry);
898	                }
899	            }
900	        }
901	        PendingTrigger::SelfDies { dead_id, dead_card_id, .. } => {
902	            if let Some(behavior) = registry.get(dead_card_id) {
903	                behavior.on_dies(state, dead_id, registry);
904	            }
905	        }
906	        PendingTrigger::DeathWatch { watcher_id, watcher_card_id, dead_id, dead_controller, dead_damaged_by, dead_toughness, .. } => {
907	            // Verify the watcher is still on the battlefield.
908	            if state.get_object(watcher_id).map(|o| o.zone == Zone::Battlefield).unwrap_or(false) {
909	                if let Some(behavior) = registry.get(watcher_card_id) {
910	                    behavior.on_any_creature_dies(state, watcher_id, dead_id, dead_controller, &dead_damaged_by, dead_toughness, registry);
911	                }
912	            }
913	        }
914	        PendingTrigger::EnterWatch { watcher_id, watcher_card_id, entered_id, entered_controller, .. } => {
915	            if state.get_object(watcher_id).map(|o| o.zone == Zone::Battlefield).unwrap_or(false) {
916	                if let Some(behavior) = registry.get(watcher_card_id) {
917	                    behavior.on_any_creature_enters(state, watcher_id, entered_id, entered_controller, registry);
918	                }
919	            }
920	        }
921	        PendingTrigger::CombatDamageToPlayer { creature_id, creature_card_id, damaged_player, amount, .. } => {
922	            if let Some(behavior) = registry.get(creature_card_id) {
923	                behavior.on_combat_damage_to_player(state, creature_id, damaged_player, amount, registry);
924	            }
925	        }
926	        PendingTrigger::CombatDamageToCreature { creature_id, creature_card_id, damaged_creature, amount, .. } => {
927	            if state.get_object(creature_id).map(|o| o.zone == Zone::Battlefield).unwrap_or(false) {
928	                if let Some(behavior) = registry.get(creature_card_id) {
929	                    behavior.on_deals_combat_damage_to_creature(state, creature_id, damaged_creature, amount, registry);
930	                }
931	            }
932	        }
933	        PendingTrigger::CombatDamageWatch { watcher_id, watcher_card_id, source_id, damaged_player, amount, .. } => {
934	            if state.get_object(watcher_id).map(|o| o.zone == Zone::Battlefield).unwrap_or(false) {
935	                if let Some(behavior) = registry.get(watcher_card_id) {
936	                    behavior.on_any_combat_damage_to_player(state, watcher_id, source_id, damaged_player, amount, registry);
937	                }
938	            }
939	        }
940	        PendingTrigger::DamageToPlayerWatch { watcher_id, watcher_card_id, source_id, damaged_player, amount, .. } => {
941	            if state.get_object(watcher_id).map(|o| o.zone == Zone::Battlefield).unwrap_or(false) {
942	                if let Some(behavior) = registry.get(watcher_card_id) {
943	                    behavior.on_any_damage_to_player(state, watcher_id, source_id, damaged_player, amount, registry);
944	                }
945	            }
946	        }
947	        PendingTrigger::EndCombatTrigger { object_id, card_id, .. } => {
948	            if state.get_object(object_id).map(|o| o.zone == Zone::Battlefield).unwrap_or(false) {
949	                if let Some(behavior) = registry.get(card_id) {
950	                    behavior.on_end_combat(state, object_id, registry);
951	                }
952	            }
953	        }
954	        PendingTrigger::UpkeepTrigger { object_id, card_id, .. } => {
955	            if state.get_object(object_id).map(|o| o.zone == Zone::Battlefield).unwrap_or(false) {
956	                if let Some(behavior) = registry.get(card_id) {
957	                    behavior.on_upkeep(state, object_id, registry);
958	                }
959	            }
960	        }
961	        PendingTrigger::EndStepTrigger { object_id, card_id, .. } => {
962	            if state.get_object(object_id).map(|o| o.zone == Zone::Battlefield).unwrap_or(false) {
963	                if let Some(behavior) = registry.get(card_id) {
964	                    behavior.on_end_step(state, object_id, registry);
965	                }
966	            }
967	        }
968	        PendingTrigger::SpellCastWatch { watcher_id, watcher_card_id, caster, spell_id, .. } => {
969	            if state.get_object(watcher_id).map(|o| o.zone == Zone::Battlefield).unwrap_or(false) {
970	                if let Some(behavior) = registry.get(watcher_card_id) {
971	                    behavior.on_spell_cast(state, watcher_id, caster, spell_id, registry);
972	                }
973	            }
974	        }
975	        PendingTrigger::LeftBattlefield { object_id, card_id, .. } => {
976	            if let Some(behavior) = registry.get(card_id) {
977	                behavior.on_leave_battlefield(state, object_id, registry);
978	            }
979	        }
980	        PendingTrigger::AttacksTrigger { object_id, card_id, .. } => {
981	            if state.get_object(object_id).map(|o| o.zone == Zone::Battlefield).unwrap_or(false) {
982	                if let Some(behavior) = registry.get(card_id) {
983	                    behavior.on_attacks(state, object_id, registry);
984	                }
985	            }
986	        }
987	        PendingTrigger::BlocksTrigger { object_id, card_id, blocked_attacker, .. } => {
988	            if state.get_object(object_id).map(|o| o.zone == Zone::Battlefield).unwrap_or(false) {
989	                if let Some(behavior) = registry.get(card_id) {
990	                    behavior.on_blocks(state, object_id, blocked_attacker, registry);
991	                }
992	            }
993	        }
994	        PendingTrigger::AttackWatch { watcher_id, watcher_card_id, attacker_id, attacker_controller, .. } => {
995	            if state.get_object(watcher_id).map(|o| o.zone == Zone::Battlefield).unwrap_or(false) {
996	                if let Some(behavior) = registry.get(watcher_card_id) {
997	                    behavior.on_any_creature_attacks(state, watcher_id, attacker_id, attacker_controller, registry);
998	                }
999	            }
1000	        }
1001	        PendingTrigger::BecomesBlockedTrigger { object_id, card_id, blocker_id, .. } => {
1002	            if state.get_object(object_id).map(|o| o.zone == Zone::Battlefield).unwrap_or(false) {
1003	                if let Some(behavior) = registry.get(card_id) {
1004	                    behavior.on_becomes_blocked(state, object_id, blocker_id, registry);
1005	                }
1006	            }
1007	        }
1008	        PendingTrigger::StateTriggered { object_id, card_id, .. } => {
1009	            // Clear the "on stack" flag so the trigger can fire again if the
1010	            // condition is still true after resolution.
1011	            if let Some(obj) = state.get_object_mut(object_id) {
1012	                obj.state_trigger_on_stack = false;
1013	            }
1014	            // Only resolve if the object is still on the battlefield.
1015	            if state.get_object(object_id).map(|o| o.zone == Zone::Battlefield).unwrap_or(false) {
1016	                if let Some(behavior) = registry.get(card_id) {
1017	                    behavior.on_state_trigger(state, object_id, registry);
1018	                }
1019	            }
1020	        }
1021	    }
1022	
1023	    true
1024	}
1025	
1026	/// Process all triggers synchronously: collect from events, push to stack,
1027	/// and resolve all triggers in LIFO order. Used by tests and code that
1028	/// doesn't go through the full game loop.
1029	pub fn process_triggers(state: &mut GameState, registry: &CardRegistry) {
1030	    collect_triggers(state, registry);
1031	
1032	    // Resolve all triggers from the stack in LIFO order.
1033	    while resolve_next_trigger(state, registry) {
1034	        // If a trigger set an awaiting_action, pause and let the caller handle it.
1035	        if state.awaiting_action.is_some() {
1036	            return;
1037	        }
1038	
1039	        // Collect any new triggers that the resolution may have caused.
1040	        collect_triggers(state, registry);
1041	    }
1042	
1043	    state.trigger_event_index = 0;
1044	}
